def run_breaker(data):
    fails = 0
    state = 'CLOSED'
    for ev in data.get('events', []):
        if not ev.get('success'):
            fails += 1
            if fails >= data.get('failure_threshold', 3):
                state = 'OPEN'
    return {'final_state': state}

